const icons={overview:'<rect x="3" y="3" width="7" height="7" rx="2"/><rect x="14" y="3" width="7" height="7" rx="2"/><rect x="3" y="14" width="7" height="7" rx="2"/><rect x="14" y="14" width="7" height="7" rx="2"/>',weekly:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M7 3v4m10-4v4M3 10h18m-13 5 3 3 5-5"/>',universities:'<path d="m2 8 10-5 10 5-10 5L2 8zm4 3v6c4 3 8 3 12 0v-6m4-3v9"/>',compare:'<rect x="3" y="4" width="18" height="16" rx="3"/><path d="M12 4v16M3 10h18"/>',checklist:'<path d="m3 6 2 2 3-4m3 2h10M3 13l2 2 3-4m3 2h10M3 20l2 2 3-4m3 2h10"/>',timeline:'<circle cx="12" cy="12" r="9"/><path d="M12 7v6l4 2"/>',funding:'<rect x="3" y="5" width="18" height="15" rx="3"/><path d="M3 10h18m-4 5h1m-5 0h1M7 3v4"/>',budget:'<rect x="5" y="2" width="14" height="20" rx="3"/><path d="M8 6h8M8 11h1m6 0h1m-8 4h1m6 0h1m-8 4h1m6 0h1"/>',applications:'<rect x="3" y="6" width="18" height="15" rx="3"/><path d="M8 6V3h8v3M3 12h18m-12 0v3h6v-3"/>',documents:'<path d="M6 2h8l5 5v15H6zM14 2v6h5M9 12h7m-7 4h7"/>',resources:'<path d="M12 5C8 2 4 3 2 4v15c3-1 7-1 10 1 3-2 7-2 10-1V4c-3-1-7-1-10 1zm0 0v15"/>',strategy:'<path d="m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3z"/>',notes:'<rect x="4" y="3" width="16" height="18" rx="3"/><path d="M8 8h8M8 12h8m-8 4h5"/>'};
const orderedViews={overview:'Overview',weekly:'This week',strategy:'Your strategy',universities:'Universities',compare:'Compare & eligibility',applications:'Applications',funding:'Funding',budget:'INR budget',checklist:'Checklist',timeline:'Timeline',documents:'Documents',resources:'Resources & benefits',notes:'Notes & settings'};Object.keys(views).forEach(k=>delete views[k]);Object.assign(views,orderedViews);
function ensureUpgrade(){state.taskMeta??={};state.comparison??={};state.funds??={};state.weekly??={};state.preferences??={theme:'light'};state.budget.awardMonths??=24;state.budget.duration??=24;state.budget.loan??=0;state.budget.emergency??=100000}
function upgradeBackup(d){const out={};for(const k of ['taskMeta','comparison','funds','weekly','preferences']){if(d[k]!==undefined){if(!d[k]||typeof d[k]!=='object'||Array.isArray(d[k]))throw Error();out[k]=d[k]}}if(out.weekly&&!Object.values(out.weekly).every(w=>w&&typeof w.goal==='number'&&w.days&&Object.values(w.days).every(n=>typeof n==='number'&&n>=0&&Number.isFinite(n))&&typeof w.reflection==='string'))throw Error();if(out.taskMeta&&!Object.values(out.taskMeta).every(m=>m&&typeof m.due==='string'&&/^$|^\d{4}-\d{2}-\d{2}$/.test(m.due)&&['Normal','High','This week'].includes(m.priority)))throw Error();return out}
ensureUpgrade();document.body.classList.toggle('dark',state.preferences.theme==='dark');
function decorateShell(page){$('#page-label').textContent=views[page];$('#nav').innerHTML=Object.entries(views).map(([k,v])=>`${k==='overview'?'<span class="nav-group">Plan</span>':k==='universities'?'<span class="nav-group">Apply</span>':k==='checklist'?'<span class="nav-group">Prepare</span>':''}<a href="#${k}" class="${k===page?'active':''}" ${k===page?'aria-current="page"':''}><span class="nav-icon"><svg viewBox="0 0 24 24" aria-hidden="true">${icons[k]}</svg></span>${v}</a>`).join('')}
function localDate(d=new Date()){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function weekDates(){const d=new Date();d.setHours(12,0,0,0);d.setDate(d.getDate()-((d.getDay()+6)%7));return Array.from({length:7},(_,i)=>{const n=new Date(d);n.setDate(d.getDate()+i);return n})}
function readiness(){const cats=['Documents','Eligibility','Exams','Applications','Funding','Visa & arrival'];return cats.map(g=>{const ts=state.tasks.filter(t=>t.group===g);return {name:g,done:ts.filter(t=>t.done).length,total:ts.length}})}
function meta(id){return state.taskMeta[id]||{due:'',priority:'Normal'}}
const baseTaskList=taskList;
taskList=function(tasks){return tasks.map(t=>{const m=meta(t.id),late=m.due&&m.due<localDate()&&!t.done;return `<div class="task ${t.done?'done':''}"><input type="checkbox" id="task-${esc(t.id)}" data-task="${esc(t.id)}" ${t.done?'checked':''}><div style="flex:1"><label for="task-${esc(t.id)}">${esc(t.title)}<small>${esc(t.note)}</small></label><div class="task-extra"><input type="date" data-task-due="${esc(t.id)}" value="${esc(m.due)}" aria-label="Due date for ${esc(t.title)}"><select data-task-priority="${esc(t.id)}" aria-label="Priority for ${esc(t.title)}">${['Normal','High','This week'].map(v=>`<option ${m.priority===v?'selected':''}>${v}</option>`).join('')}</select>${late?'<span class="task-overdue">Past your target date</span>':''}</div></div>${t.id.startsWith('custom')?`<button data-delete="${esc(t.id)}" aria-label="Delete task">×</button>`:''}</div>`}).join('')};
overview=function(){const done=state.tasks.filter(t=>t.done).length,pct=Math.round(done/state.tasks.length*100),due=state.tasks.filter(t=>!t.done&&meta(t.id).due&&meta(t.id).due<=localDate()).length,awards=Object.values(state.funds).filter(f=>f.status==='Awarded').length;return `<div class="welcome-row"><div><h1>Your next chapter.</h1><p class="intro">Let’s make Germany a well-prepared next step, Kamyavardhan.</p></div><span class="date">${new Date().toLocaleDateString('en-IN',{weekday:'long',day:'numeric',month:'long'})}</span></div><section class="journey-hero"><div><span class="pill">Winter 2027/28 · summer 2028 backup</span><h2>Big ambition.<br>A clear plan.</h2><p>A master’s in Data Science or AI/ML, with academic fit and affordable funding at the centre.</p><button class="primary" data-go="weekly">Plan this week</button></div><div class="hero-art" aria-hidden="true"><div class="destination"><span class="stamp">Your next destination</span><strong>Germany</strong><div class="ticket-line"></div><small>Jodhpur → a new chapter<br>Master’s · 2027 / 2028</small></div><div class="orbit-dot">✦</div></div></section><div class="stats"><div class="stat"><small>Journey progress</small><strong>${pct}%</strong><small>${done} of ${state.tasks.length} tasks complete</small><div class="progress"><div style="width:${pct}%"></div></div></div><div class="stat"><small>University shortlist</small><strong>${state.shortlist.length}<span style="font-size:14px;color:var(--muted)"> / 5</span></strong><small>Researched tuition-free options</small></div><div class="stat"><small>Funding tracker</small><strong>${awards}</strong><small>Awards marked secured · ${due} tasks due</small></div></div><div class="section-title"><h2>Make progress where it matters.</h2><a href="#strategy">View your strategy</a></div><div class="overview-grid"><section class="panel"><h3>Next useful actions</h3><p class="panel-subtitle">Start with the documents that unlock your applications.</p>${taskList(state.tasks.filter(t=>!t.done).sort((a,b)=>(meta(b.id).priority==='This week')-(meta(a.id).priority==='This week')).slice(0,3))}<div class="links"><a href="#checklist">All tasks</a><a href="#timeline">Timeline</a></div></section><section class="panel"><h3>Preparation, at a glance</h3><p class="panel-subtitle">Based on completed tasks, not admission chances.</p>${readiness().map(g=>`<div class="readiness"><span>${g.name}</span><span>${g.done}/${g.total}</span><div class="progress"><div style="width:${g.total?100*g.done/g.total:0}%"></div></div></div>`).join('')}</section><section class="panel"><h3>Your strongest next moves</h3>${[['1','Check subject fit first','Match mathematics, statistics and CS evidence before paying application fees.'],['2','Run two funding searches','Germany-only scholarships, plus Erasmus Mundus if multi-country study suits you.'],['3','Build evidence, not a certificate pile','Refine one strong project and get specific academic references.']].map(([n,t,d])=>`<div class="focus-item"><span class="focus-icon">${n}</span><div><b>${t}</b><p>${d}</p></div></div>`).join('')}</section><section class="panel"><h3>Your reference desk</h3><a class="mini-link" href="#universities"><span>Compare tuition-free programmes</span><span>5 options</span></a><a class="mini-link" href="#budget"><span>Plan costs in rupees</span><span>Calculator</span></a><a class="mini-link" href="#resources"><span>Prepare with free resources</span><span>Study & benefits</span></a><a class="mini-link" href="#documents"><span>Organise your documents</span><span>Sem 1–6 ready to scan</span></a></section></div><div class="notice"><b>Current dependency:</b> semester 7 results are expected January–February 2027. Confirm dMAT / APS timing for your completed-semester status before paying. Your passport is the first practical step.</div>`};
function weekly(){const dates=weekDates(),key=localDate(dates[0]);const w=state.weekly[key]||{goal:8,days:{},reflection:''};const mins=Object.values(w.days).reduce((s,n)=>s+Number(n),0);return heading('Small steps. Every week.','A realistic preparation rhythm alongside your final-year coursework. Hours are a personal planning target.')+`<div class="grid"><section class="panel"><span class="pill">Week of ${dates[0].toLocaleDateString('en-IN',{day:'numeric',month:'long'})}</span><h2>Your focus time</h2><div class="metric-number" id="weekly-total">${(mins/60).toFixed(1)} <span style="font-size:16px;color:var(--muted)">hours logged</span></div><label>Weekly goal in hours <input type="number" min="1" max="60" value="${w.goal}" data-week-goal="${key}" aria-label="Weekly goal in hours" style="width:70px"></label><p class="panel-subtitle">Log minutes below. No timer or background monitoring is active.</p></section><section class="panel"><h3>A suggested 8-hour split</h3><p>3 hours English preparation<br>2 hours university / scholarship research<br>2 hours project evidence or academic revision<br>1 hour documents and application administration</p><small>Adjust around December exams. Protect grades and sleep; more hours are not automatically better.</small></section></div><div class="week-days">${dates.map(d=>{const date=localDate(d);return `<label class="day ${date===localDate()?'today':''}"><span>${d.toLocaleDateString('en-IN',{weekday:'short'})}</span><b>${d.getDate()}</b><input type="number" min="0" max="1440" value="${w.days[date]||0}" data-week-day="${date}" data-week-key="${key}" aria-label="Minutes for ${date}"><span>minutes</span></label>`}).join('')}</div><div class="section-title"><h2>Your focus tasks</h2><a href="#checklist">Choose tasks in checklist</a></div><section class="panel">${taskList(state.tasks.filter(t=>!t.done&&(meta(t.id).priority==='This week'||(meta(t.id).due&&meta(t.id).due>=key&&meta(t.id).due<=localDate(dates[6])))))||'<p class="empty">Choose “This week” on a checklist task or set a due date this week.</p>'}</section><h2>Weekly review</h2><div class="panel"><label for="week-reflection">What moved forward? What is blocked? What will you do next?</label><textarea id="week-reflection" data-week-reflection="${key}" placeholder="Record one win, one blocker and the next action…">${esc(w.reflection)}</textarea></div>`}
function strategy(){const steps=[['Protect academic eligibility','Use marksheets and the syllabus to map actual completed courses. Request first-year mathematics details, official credits, teaching hours and a grading scale. A high CGPA cannot replace missing subject prerequisites.','compare','Open eligibility comparison'],['Make one project excellent','Choose the healthcare or computer-vision project you can defend best. Record the dataset, your contribution, baseline, evaluation, limitations and reproducible code. Write a short technical explanation; avoid unsupported impact claims.','checklist','Add evidence tasks'],['Build a funding portfolio','Keep Germany-only options and joint European programmes in separate lanes. Compare grant versus loan, coverage, duration, deadline and repayment. A funding application deserves its own tailored motivation.','funding','Explore funding routes'],['Prepare English with a target','Take a diagnostic, work on your weakest sections and verify accepted scores programme by programme. C1 is a programme requirement to translate into accepted test scores, not a universal IELTS number.','resources','Open free preparation'],['Get specific academic references','Ask two professors who know your work and can discuss research ability, mathematics and independent learning. Share your CV, project evidence and target programmes well before the deadline.','documents','Organise evidence'],['Submit fewer weak applications','Prioritise formal fit, subject fit, cost and funding. Confirm whether provisional results are accepted and when final evidence is due. Submit early enough to resolve missing documents.','applications','Track applications'],['Learn German steadily','Use free courses for everyday communication, housing and work readiness. English-taught admission does not remove the value of German for daily life. Set a sustainable study habit.','resources','Open German resources'],['Keep the arrival plan affordable','Research student housing early, retain a cash buffer and budget without assuming immediate employment. Refresh visa funding and health-insurance requirements before departure.','budget','Review the funding gap']];return heading('Maximise what matters.','A focused strategy for strong applications and lower family contribution. These are actions you control, not promises of admission or funding.')+`<div class="notice"><b>Your starting position:</b> 9.31 CGPA, AI/ML projects and a research internship are useful evidence. The highest-value next step is checking formal eligibility and funding timing, then improving the quality of that evidence.</div><div class="panel">${steps.map(([t,d,p,l],i)=>`<div class="strategy-row"><span class="strategy-number">${i+1}</span><div><h3>${t}</h3><p>${d}</p><a href="#${p}">${l}</a></div></div>`).join('')}</div><h2>Three decisions to make deliberately</h2><div class="grid"><div class="panel"><h3>Germany-only or multi-country?</h3><p>Erasmus Mundus programmes may accept final-year applicants and offer substantial scholarships, but involve several countries. Check that a specific consortium includes Germany if that is important to you.</p>${link('https://erasmus-plus.ec.europa.eu/opportunities/opportunities-for-individuals/students/erasmus-mundus-joint-masters-scholarships','Official Erasmus Mundus guidance')}</div><div class="panel"><h3>Start date or funding first?</h3><p>Keep winter 2027/28 primary and summer 2028 backup. If no affordable offer materialises, compare the cost of waiting with accepting an unfunded place. Summer admission alone does not establish scholarship availability.</p><a href="#funding">Check funding windows</a></div></div>`}
function compare(){return heading('Compare before you commit.','Your subject-fit worksheet. Record evidence and unresolved questions; this does not calculate admission probability.')+`<div class="notice">Programmes can require very different mathematics and computer-science backgrounds. Indian course credits are not automatically ECTS. Use official regulations and ask the admissions team when equivalence is unclear. No transcript-based eligibility assessment has been completed yet.</div><div class="panel table-wrap"><table class="comparison"><thead><tr><th>Programme</th>${universities.map(u=>`<th>${u.name}</th>`).join('')}</tr></thead><tbody><tr><td>Focus</td>${universities.map(u=>`<td>${u.course}<p>${u.fit}</p></td>`).join('')}</tr><tr><td>Current tuition</td>${universities.map(u=>`<td><span class="tag">₹0 listed</span><small>Reconfirm 2027/28 policy</small></td>`).join('')}</tr><tr><td>Admission checks</td>${universities.map(u=>`<td>${u.requirements}</td>`).join('')}</tr><tr><td>Intake & deadlines</td>${universities.map(u=>`<td>${u.intake}<p>${u.deadline}</p></td>`).join('')}</tr><tr><td>My fit assessment</td>${universities.map(u=>`<td><select data-fit="${u.id}" aria-label="Eligibility assessment for ${u.name}">${['Not assessed','Need clarification','Evidence collected','Requirements appear met','Does not fit'].map(v=>`<option ${state.comparison[u.id]?.status===v?'selected':''}>${v}</option>`).join('')}</select><textarea class="compare-note" data-fit-note="${u.id}" aria-label="Eligibility evidence for ${u.name}" placeholder="Math/CS/statistics credits, syllabus pages, English proof, questions…">${esc(state.comparison[u.id]?.note||'')}</textarea></td>`).join('')}</tr><tr><td>Verify</td>${universities.map(u=>`<td>${link(u.url,'Official programme')}</td>`).join('')}</tr></tbody></table></div><h2>Evidence we still need</h2><div class="panel"><p>Semester 1–6 marksheet contents; first-year syllabus; actual electives; official grading scale; degree-awarding university confirmation; semester 7 results; English test evidence.</p><p class="muted">“Requirements appear met” is your planning status, not university approval.</p></div>`}
const fundRoutes=[
{id:'erasmus',name:'Erasmus Mundus Joint Masters',type:'Grant / scholarship',status:'Research target programmes',text:'Full scholarships are available to top-ranked applicants in participating programmes. Official guidance permits last-year bachelor’s students who graduate before the master’s starts. Mobility across countries is part of the route.',timing:'Many applications fall between October and January; every consortium sets its own deadline. Check 2027 entry now.',url:'https://erasmus-plus.ec.europa.eu/opportunities/opportunities-for-individuals/students/erasmus-mundus-joint-masters-scholarships'},
{id:'stem',name:'DAAD STEM study scholarship',type:'Grant / scholarship',status:'Eligibility unresolved',text:'Current call requires a completed first degree by the application deadline and a tuition-free programme. Match your graduation date with the India-specific deadline; do not assume final-year eligibility.',timing:'Country-specific call and funded intake must be checked.',url:'https://www2.daad.de/deutschland/stipendium/datenbank/en/21148-scholarship-database/?detail=57742130'},
{id:'nsf',name:'Narotam Sekhsaria Foundation',type:'Repayable interest-free assistance',status:'Monitor next cycle',text:'The published 2026 rules permitted final-year students / applicants awaiting results. Indian nationality/residence, age, admission and selection conditions apply. It is repayable financial assistance.',timing:'2026 applications closed. Do not reuse the old deadline for 2027.',url:'https://pg.nsfoundation.co.in/application-process'},
{id:'mahindra',name:'K. C. Mahindra postgraduate support',type:'Interest-free loan scholarship',status:'Monitor next cycle',text:'Official information describes interest-free loan scholarships, with awards up to ₹10 lakh for the top three fellows and up to ₹5 lakh for other awardees. Verify the next cycle’s amount and eligibility.',timing:'The published overseas start window is August 2026–February 2027, which does not match your target. Await next call.',url:'https://kcmet.org/what-we-do-Scholarship-Grants.aspx'},
{id:'tata',name:'J. N. Tata Endowment',type:'Loan scholarship',status:'Monitor next cycle',text:'Current FAQ describes a loan scholarship up to ₹20 lakh, with 2% simple interest and discretionary rebates. Repayment terms apply; the maximum award is not guaranteed.',timing:'Published eligibility is for 2026. Verify future cycle and final-year policy before applying.',url:'https://jntataendowment.org/faqs'},
{id:'university',name:'University awards & Deutschlandstipendium',type:'Usually partial support',status:'Research per university',text:'Check eligibility for incoming international students, award duration, selection and compatibility with other support. An award after enrolment may not solve pre-departure proof of funds.',timing:'Each university sets its own application window.',url:'https://www.deutschlandstipendium.de/'},
{id:'epos',name:'DAAD EPOS',type:'Grant / scholarship',status:'Not a current fit',text:'Requires at least two years of relevant professional experience after the bachelor’s. This does not fit your immediate post-bachelor timeline.',timing:'Keep outside the immediate funding plan.',url:'https://www2.daad.de/deutschland/stipendium/datenbank/en/21148-scholarship-database?detail=50076777'}
];
funding=function(){return heading('More routes. Clearer trade-offs.','Separate scholarships from loans, and promising opportunities from confirmed money.')+`<div class="notice">2026 calls are reference evidence, not open 2027 applications. New funding research checked 11 November 2026. Award amounts and next-cycle deadlines need confirmation. Changing a tracker status does not update the budget automatically.</div><div class="grid">${fundRoutes.map(f=>`<section class="panel fund-card"><div><span class="tag">${f.type}</span><h3>${f.name}</h3><span class="pill">${f.status}</span><p>${f.text}</p><p class="muted" style="font-size:12px">${f.timing}</p>${link(f.url,'Official eligibility & application information')}</div><div class="fund-controls"><label class="score-label" for="fund-${f.id}">My progress</label><select id="fund-${f.id}" data-fund="${f.id}">${['Not started','Checking eligibility','Preparing','Applied','Awarded','Not eligible / closed'].map(v=>`<option ${state.funds[f.id]?.status===v?'selected':''}>${v}</option>`).join('')}</select></div><textarea class="fund-note" data-fund-note="${f.id}" aria-label="Notes for ${f.name}" placeholder="Deadline, amount, duration, documents, repayment and open questions…">${esc(state.funds[f.id]?.note||'')}</textarea></section>`).join('')}</div><h2>Before counting an award</h2><section class="panel"><p>Record the award letter, payment timing, covered months, tuition, insurance, travel, restrictions and any repayment. Confirm whether the visa authority accepts it as financial proof. Enter only the awarded amount and duration in the budget.</p><a href="#budget">Calculate the remaining funding gap</a></section>`};
const originalBudget=budget;
budget=function(){return originalBudget().replace('<div id="budget-results"></div>',`<section class="panel" style="margin-top:16px"><h3>Make the funding scenario realistic</h3><div class="fields">${[['duration','Study duration in months'],['awardMonths','Scholarship-covered months'],['loan','Confirmed loan / repayable support in ₹'],['emergency','Emergency buffer in ₹']].map(([k,l])=>`<label>${l}<input type="number" min="0" max="${['duration','awardMonths'].includes(k)?120:100000000}" data-budget="${k}" value="${state.budget[k]}"></label>`).join('')}</div><p class="muted">Loans can reduce the immediate cash gap but do not reduce your study cost. The housing deposit is extra cash tied up, not ordinary spending.</p></section><div id="budget-results"></div>`).replace('Scholarship calculation assumes 24 covered months; change the monthly figure to an equivalent average if coverage is shorter. Savings are separate from family funds.','Enter the actual monthly award and covered months below. Savings are your own funds, separate from family support.')};
budgetResults=function(){const b=state.budget,r=b.rate,months=b.duration,terms=Math.ceil(months/6),prep=39500+345*r+10000,setup=110000+425*r,living=months*b.monthly*r,sem=terms*b.semester*r,tuition=terms*b.tuition*r,total=prep+setup+living+sem+tuition+b.emergency,grant=Math.min(months,b.awardMonths)*b.scholarship*r,gap=Math.max(0,total-grant-b.savings-b.loan),deposit=1000*r,arrival=prep+setup+b.semester*r+b.tuition*r+11904*r+deposit+b.emergency;$('#budget-results').innerHTML=`<div class="stats" style="margin:22px 0"><div class="stat"><small>Estimated spending + buffer</small><strong>${money(total)}</strong><small>${months} months · ${terms} semesters</small></div><div class="stat"><small>Remaining cash gap</small><strong>${money(gap)}</strong><small>After entered grant, savings and loan</small></div><div class="stat"><small>Borrowing to repay</small><strong>${money(b.loan)}</strong><small>Interest / repayment not calculated</small></div></div><div class="panel table-wrap"><table>${[['Preparation: passport, IELTS, APS, dMAT provision, 5 uni-assist courses and ₹10k documents/travel',prep],['Flight / setup ₹1.10 lakh + visa / provider / residence allowances €425',setup],[`${months} months living, including ordinary health insurance`,living],[`${terms} semester contributions`,sem],[`${terms} semesters tuition`,tuition],['Emergency reserve (unspent unless needed)',b.emergency],['Entered scholarship support',grant],['Your own savings',b.savings],['Loan / repayable support (cash, not a cost reduction)',b.loan]].map(([t,v])=>`<tr><td>${t}</td><td>${money(v)}</td></tr>`).join('')}</table><h3 style="margin-top:22px">Cash needed around departure</h3><p>Illustrative no-scholarship scenario: <b>${money(arrival)}</b>, including current first-year blocked funds, preparation/setup, first semester fees, a €1,000 housing deposit assumption and your buffer. This is a cash-flow estimate, not additional spending on top of the degree total.</p><p>Housing deposit: <b>${money(deposit)}</b> extra cash, potentially refundable. Current annual blocked-account benchmark: <b>${money(11904*r)}</b>. Do not add the blocked amount again to living costs. Recognised scholarship evidence may change the deposit required; no automatic visa eligibility is calculated.</p><small>Future visa amounts, exchange spreads, fee changes and applicable remittance tax collection are excluded. Refresh quotes before transferring.</small></div>`};
function weekRecord(key){return state.weekly[key]??=( {goal:8,days:{},reflection:''})}
document.addEventListener('input',e=>{const t=e.target;if(t.dataset.fitNote){state.comparison[t.dataset.fitNote]={...state.comparison[t.dataset.fitNote],note:t.value};save()}if(t.dataset.fundNote){state.funds[t.dataset.fundNote]={...state.funds[t.dataset.fundNote],note:t.value};save()}if(t.dataset.weekDay){weekRecord(t.dataset.weekKey).days[t.dataset.weekDay]=Math.min(1440,Math.max(0,Number(t.value)||0));save();const total=Object.values(state.weekly[t.dataset.weekKey].days).reduce((s,n)=>s+n,0);$('#weekly-total').innerHTML=`${(total/60).toFixed(1)} <span style="font-size:16px;color:var(--muted)">hours logged</span>`}if(t.dataset.weekGoal){weekRecord(t.dataset.weekGoal).goal=Math.min(60,Math.max(1,Number(t.value)||1));save()}if(t.dataset.weekReflection){weekRecord(t.dataset.weekReflection).reflection=t.value;save()}});
document.addEventListener('change',e=>{const t=e.target;if(t.dataset.taskDue){state.taskMeta[t.dataset.taskDue]={...meta(t.dataset.taskDue),due:t.value};save()}if(t.dataset.taskPriority){state.taskMeta[t.dataset.taskPriority]={...meta(t.dataset.taskPriority),priority:t.value};save()}if(t.dataset.fit){state.comparison[t.dataset.fit]={...state.comparison[t.dataset.fit],status:t.value};save()}if(t.dataset.fund){state.funds[t.dataset.fund]={...state.funds[t.dataset.fund],status:t.value};save()}});
function searchWorkspace(){const q=$('#global-search').value.trim().toLowerCase(),pages=Object.entries(views).map(([id,title])=>({title,url:'#'+id,kind:'Page'})),us=universities.map(u=>({title:u.name+' · '+u.course,url:'#universities',kind:'University'})),ts=state.tasks.map(t=>({title:t.title,url:'#checklist',kind:t.group})),fs=fundRoutes.map(f=>({title:f.name,url:'#funding',kind:f.type}));$('#search-results').innerHTML=[...pages,...us,...ts,...fs].filter(r=>!q||r.title.toLowerCase().includes(q)).slice(0,12).map(r=>`<a href="${r.url}" data-search-result><small>${r.kind}</small>${esc(r.title)}</a>`).join('')||'<p class="empty">No matches. Try “IELTS”, “funding” or a university name.</p>'}
function openSearch(){$('#search-dialog').showModal();$('#global-search').value='';searchWorkspace();$('#global-search').focus()}
$('#search-open').addEventListener('click',openSearch);$('#search-close').addEventListener('click',()=>$('#search-dialog').close());$('#global-search').addEventListener('input',searchWorkspace);$('#search-results').addEventListener('click',e=>{if(e.target.closest('[data-search-result]'))$('#search-dialog').close()});document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openSearch()}});
$('#theme-toggle').addEventListener('click',()=>{state.preferences.theme=state.preferences.theme==='dark'?'light':'dark';document.body.classList.toggle('dark',state.preferences.theme==='dark');save()});
function calendarExport(){const rows=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Germany Study Path//Tasks//EN','CALSCALE:GREGORIAN'];for(const t of state.tasks.filter(t=>meta(t.id).due&&!t.done)){const date=meta(t.id).due.replaceAll('-','');rows.push('BEGIN:VEVENT',`UID:${t.id}@germany-study-path`,`DTSTAMP:${new Date().toISOString().replace(/[-:]/g,'').split('.')[0]}Z`,`DTSTART;VALUE=DATE:${date}`,'SUMMARY:'+t.title.replaceAll('\\','\\\\').replaceAll(',','\\,').replaceAll(';','\\;').replaceAll('\n','\\n'),'DESCRIPTION:Personal target date. Verify official deadlines separately.','END:VEVENT')}rows.push('END:VCALENDAR');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([rows.join('\r\n')],{type:'text/calendar'}));a.download='germany-personal-task-dates.ics';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Calendar file exported. Import it into your calendar.')}
const oldChecklist=checklist;checklist=function(){return oldChecklist().replace('<form id="task-form"',`<div class="toolbar"><button id="calendar-export">Export dated tasks to calendar</button><span class="muted" style="font-size:11px">Personal target dates; calendar alerts depend on your calendar app.</span></div><form id="task-form"`)};document.addEventListener('click',e=>{if(e.target.closest('#calendar-export'))calendarExport()});
const oldNotes=notes;notes=function(){return oldNotes()+`<div class="panel mobile-backup" style="margin-top:18px"><h3>Back up this device</h3><p>Export your progress before switching browsers or devices. Import replaces the current workspace with your backup.</p><button id="export-mobile">Export backup</button><label class="import">Import backup<input id="import-mobile" type="file" accept="application/json"></label></div><div class="panel" style="margin-top:18px"><h3>Use this like an app</h3><p>Where your browser supports it, use its Install app / Add to Home Screen option. After one successful visit, core pages can work offline. Official external resources require an internet connection.</p><p class="muted">Progress is device-local. There is no account sync, automatic web monitoring, background reminder or secure document upload in this version.</p></div>`};document.addEventListener('click',e=>{if(e.target.closest('#export-mobile'))exportData()});document.addEventListener('change',e=>{if(e.target.id==='import-mobile'){const dt=new DataTransfer();if(e.target.files[0])dt.items.add(e.target.files[0]);$('#import').files=dt.files;$('#import').dispatchEvent(new Event('change'))}});
if('serviceWorker' in navigator)navigator.serviceWorker.register('sw.js').catch(()=>{});
render();

// Phone navigation is separate from the sidebar, so desktop behaviour stays intact.
const dockPrimary=[['overview','Home'],['universities','Explore'],['checklist','Tasks'],['budget','Budget']];
const phoneQuery=matchMedia('(max-width: 700px)');
const mobileDock=document.createElement('nav');
mobileDock.id='mobile-dock';mobileDock.setAttribute('aria-label','Phone navigation');
const mobileMore=document.createElement('dialog');
mobileMore.id='mobile-more';mobileMore.setAttribute('aria-labelledby','mobile-more-title');
document.body.append(mobileDock,mobileMore);
const dockStyles=document.createElement('link');dockStyles.rel='stylesheet';dockStyles.href='dock.css';document.head.append(dockStyles);
function dockIcon(key){return `<svg viewBox="0 0 24 24" aria-hidden="true">${icons[key]}</svg>`}
function updatePhoneNavigation(page){
  const secondary=!dockPrimary.some(([id])=>id===page);
  mobileDock.innerHTML=dockPrimary.map(([id,label])=>`<a href="#${id}" class="dock-item ${id===page?'selected':''}" ${id===page?'aria-current="page"':''}><span class="dock-symbol">${dockIcon(id)}</span><span>${label}</span></a>`).join('')+`<button type="button" id="dock-more" class="dock-item ${secondary?'selected':''}" aria-label="More sections" aria-haspopup="dialog" aria-controls="mobile-more" aria-expanded="${mobileMore.open}"><span class="dock-symbol"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="5" cy="12" r="1.5"/><circle cx="12" cy="12" r="1.5"/><circle cx="19" cy="12" r="1.5"/></svg></span><span>More</span></button>`;
  mobileMore.innerHTML=`<div class="sheet-handle" aria-hidden="true"></div><div class="sheet-header"><div><h2 id="mobile-more-title">Your workspace</h2><p>Everything for your next chapter.</p></div><button type="button" id="dock-more-close" aria-label="Close more sections">×</button></div><div class="sheet-links">${Object.entries(views).filter(([id])=>!dockPrimary.some(([primary])=>primary===id)).map(([id,label])=>`<a href="#${id}" class="sheet-link ${page===id?'selected':''}" ${page===id?'aria-current="page"':''}><span class="sheet-icon">${dockIcon(id)}</span><span>${label}</span><span class="sheet-chevron" aria-hidden="true">›</span></a>`).join('')}</div>`;
}
const shellBeforeDock=decorateShell;
decorateShell=function(page){shellBeforeDock(page);updatePhoneNavigation(page)};
mobileDock.addEventListener('click',e=>{if(e.target.closest('#dock-more')){mobileMore.showModal();$('#dock-more').setAttribute('aria-expanded','true')}});
function closePhoneMenu(){mobileMore.close();$('#dock-more')?.setAttribute('aria-expanded','false')}
mobileMore.addEventListener('click',e=>{if(e.target===mobileMore||e.target.closest('#dock-more-close')||e.target.closest('a'))closePhoneMenu()});
mobileMore.addEventListener('close',()=>$('#dock-more')?.setAttribute('aria-expanded','false'));
window.addEventListener('hashchange',()=>{if(mobileMore.open)closePhoneMenu()});
phoneQuery.addEventListener('change',e=>{if(!e.matches&&mobileMore.open)closePhoneMenu()});
updatePhoneNavigation(location.hash.slice(1)||'overview');
